// Compatibility renderer for browsers with WebGL unavailable.
// Uses the same scene, camera, geometry, collision and animation as the main renderer.
import * as T from './assets/three.module.js';
const point=new T.Vector3(),world=new T.Vector3(),scale=new T.Vector3(),q=new T.Quaternion();
export class SoftwareRenderer {
 constructor({canvas}){this.canvas=canvas;this.ctx=canvas.getContext('2d');if(!this.ctx)throw Error('No drawing context');this.ratio=1;this.color='#d8d8d4';this.compatibility=true;this.last=0;}
 setPixelRatio(r){this.ratio=Math.min(r,1.25)}
 setSize(w,h){this.w=w;this.h=h;this.canvas.width=w*this.ratio;this.canvas.height=h*this.ratio;this.canvas.style.width=w+'px';this.canvas.style.height=h+'px'}
 setClearColor(c){this.color='#'+c.toString(16).padStart(6,'0')}
 render(scene,camera){const now=performance.now();if(now-this.last<30)return;this.last=now;const ctx=this.ctx,w=this.w,h=this.h;ctx.setTransform(this.ratio,0,0,this.ratio,0,0);ctx.fillStyle=this.color;ctx.fillRect(0,0,w,h);ctx.fillStyle='#adadaa';ctx.fillRect(0,h*.22,w,h);scene.updateMatrixWorld(true);camera.updateMatrixWorld(true);const view=camera.matrixWorldInverse,draw=[];
 const project=(x,y,z,m)=>{point.set(x,y,z).applyMatrix4(m);let depth=point.clone().applyMatrix4(view).z;if(depth>-.15)return null;point.project(camera);return {x:(point.x*.5+.5)*w,y:(-.5*point.y+.5)*h,depth}};
 scene.traverseVisible(o=>{if(!(o.isMesh||o.isSprite)||o.material.side===T.BackSide)return;const p=o.geometry?.parameters||{},type=o.geometry?.type;if(type==='PlaneGeometry'&&!o.material.map)return;o.matrixWorld.decompose(world,q,scale);point.copy(world).applyMatrix4(view);let depth=point.z;if(depth>-.2||depth<-70)return;let center=project(0,0,0,o.matrixWorld);if(!center)return;let base=o.material.color?.getHex()??0xffffff,r=(base>>16)&255,g=(base>>8)&255,b=base&255;const color=(factor=1)=>`rgb(${Math.min(255,r*factor)|0},${Math.min(255,g*factor)|0},${Math.min(255,b*factor)|0})`,unit=h/(2*Math.tan(camera.fov*Math.PI/360)*-depth);if(o.isSprite){let img=o.material.map?.image;const sw=scale.x*unit,sh=scale.y*unit;if(img)draw.push({depth,run:()=>{ctx.drawImage(img,center.x-sw/2,center.y-sh/2,sw,sh)}});return;}
 if(type==='SphereGeometry'||type==='CircleGeometry'){let rad=p.radius||1,rx=scale.x*rad*unit,ry=scale.y*rad*unit;if(type==='CircleGeometry'){ry=rx*.38}if(center.x+rx<0||center.x-rx>w||center.y+ry<0||center.y-ry>h)return;draw.push({depth,run:()=>{ctx.globalAlpha=o.material.opacity??1;ctx.beginPath();ctx.ellipse(center.x,center.y,Math.max(.2,rx),Math.max(.2,ry),0,0,Math.PI*2);ctx.fillStyle=color(1.16);ctx.fill();if(type!=='CircleGeometry'){ctx.strokeStyle='#282a25';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();ctx.ellipse(center.x+rx*.15,center.y+ry*.17,Math.max(.1,rx*.8),Math.max(.1,ry*.72),0,0,Math.PI);ctx.fillStyle=color(.83);ctx.fill()}ctx.globalAlpha=1}});return;}
 if(type==='PlaneGeometry'&&o.material.map?.image){const img=o.material.map.image;const nx=Math.max(1,Math.ceil(p.width/5)),ny=Math.max(1,Math.ceil(p.height/5));for(let ix=0;ix<nx;ix++)for(let iy=0;iy<ny;iy++){const x0=-p.width/2+ix*p.width/nx,x1=x0+p.width/nx,y0=-p.height/2+iy*p.height/ny,y1=y0+p.height/ny;const pts=[[x0,y1],[x1,y1],[x1,y0],[x0,y0]].map(([x,y])=>project(x,y,0,o.matrixWorld));if(pts.some(p=>!p))continue;draw.push({depth:-1000,run:()=>{const tri=(a,b,c,uv)=>{ctx.save();ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.closePath();ctx.clip();const [u0,v0,u1,v1,u2,v2]=uv,den=(u1-u0)*(v2-v0)-(u2-u0)*(v1-v0),aa=((b.x-a.x)*(v2-v0)-(c.x-a.x)*(v1-v0))/den,bb=((b.y-a.y)*(v2-v0)-(c.y-a.y)*(v1-v0))/den,cc=((c.x-a.x)*(u1-u0)-(b.x-a.x)*(u2-u0))/den,dd=((c.y-a.y)*(u1-u0)-(b.y-a.y)*(u2-u0))/den;ctx.transform(aa,bb,cc,dd,a.x-aa*u0-cc*v0,a.y-bb*u0-dd*v0);ctx.drawImage(img,0,0,1,1);ctx.restore()};tri(pts[0],pts[1],pts[3],[0,0,1,0,0,1]);tri(pts[1],pts[2],pts[3],[1,0,1,1,0,1])}})}return;}
 const a=o.geometry?.attributes.position;if(!a)return;const index=o.geometry.index?.array,faces=[],len=index?.length??a.count;let matrix=o.matrixWorld;for(let j=0;j<len;j+=3){let ids=index?[index[j],index[j+1],index[j+2]]:[j,j+1,j+2],ps=ids.map(i=>project(a.getX(i),a.getY(i),a.getZ(i),matrix));if(ps.some(p=>!p))continue;let [v1,v2,v3]=ps,cross=(v2.x-v1.x)*(v3.y-v1.y)-(v2.y-v1.y)*(v3.x-v1.x);if(o.material.side!==T.DoubleSide&&cross>=0)continue;if(ps.every(p=>p.x<0)||ps.every(p=>p.x>w)||ps.every(p=>p.y<0)||ps.every(p=>p.y>h))continue;let factor=.88+(j%12)/60;faces.push({ps,depth:(v1.depth+v2.depth+v3.depth)/3,fill:color(factor)})}
 faces.sort((a,b)=>a.depth-b.depth);draw.push({depth:Math.abs(world.y)<.08?-1100:depth,run:()=>{ctx.globalAlpha=o.material.opacity??1;for(let {ps,fill}of faces){ctx.beginPath();ctx.moveTo(ps[0].x,ps[0].y);ctx.lineTo(ps[1].x,ps[1].y);ctx.lineTo(ps[2].x,ps[2].y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle=fill;ctx.lineWidth=.5;ctx.stroke()}ctx.globalAlpha=1}})
 });draw.sort((a,b)=>a.depth-b.depth);for(let d of draw)d.run();
 }
}
